 p_id=>wwv_flow_imp.id(8792902995571077704)
,p_plug_name=>'Employees'
,p_static_id=>'search-results'
,p_region_name=>'search-results'
,p_region_template_options=>'#DEFAULT#:t-ContentBlock--h1:t-ContentBlock--lightBG:t-Region--removeHeader js-removeLandmark'
,p_plug_template=>2325543309974442989
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select fe.first_name||'' ''||fe.last_name as name',
'      ,fe.job_title',
'      ,fcc.business_unit',
'      ,fe.email',
'      ,fe.phone_country_code||'' ''||fe.phone_number phone_number',
'      ,fe.tags',
'      ,initcap(fe.work_arrangement) work_arrangement',
'      ,TO_CHAR(fe.hire_date, ''DD Mon YYYY'') AS HIRE_DATE_DISPLAY',
'      ,fe.hire_date AS HIRE_DATE',
'      ,initcap(fe.employment_status) employment_status',
'      ,fe.country',
'      ,fe.career_level',
'      ,case fe.employment_status when ''ACTIVE'' then ''success'' ',
'            when ''INACTIVE'' then ''danger''',
'            when ''LEAVE'' then ''warning''',
'       end badge_state',
'      ,case fe.employment_status when ''ACTIVE'' then ''fa-check-circle-o'' ',
'            when ''INACTIVE'' then ''fa-times-circle-o''',
'            when ''LEAVE'' then ''fa-minus-circle-o''',
'       end badge_icon',
'     , avatar',
'     ,fe.employee_id',
'from fsp_employees fe',
'join fsp_cost_centers fcc',
'on fe.cost_center_id = fcc.cost_center_id'))
,p_query_order_by_type=>'ITEM'
,p_query_order_by=>'{"orderBys":[{"key":"REPORTS1","expr":"HIRE_DATE DESC"},{"key":"REPORTS2","expr":"HIRE_DATE ASC"},{"key":"JOB","expr":"JOB_TITLE ASC"},{"key":"ENAME","expr":"NAME ASC"}],"itemName":"P4_ORDER_BY"}'
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$CONTENT_ROW'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>false
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'APPLY_THEME_COLORS', 'N',
  'AVATAR_IMAGE', '{"source":"URL","url":"#APEX_FILES#sample_data&AVATAR."}',
  'AVATAR_SHAPE', 't-Avatar--rounded',
  'AVATAR_TYPE', 'image',
  'BADGE_COL_WIDTH', 't-ContentRow-badge--lg',
  'BADGE_ICON', '&BADGE_ICON.',
  'BADGE_LABEL', 'Status',
  'BADGE_LABEL_DISPLAY', 'N',
  'BADGE_SHAPE', 't-Badge--circle',
  'BADGE_STATE', 'BADGE_STATE',
  'BADGE_STYLE', 't-Badge--subtle',
  'BADGE_VALUE', 'EMPLOYMENT_STATUS',
  'DESCRIPTION', wwv_flow_string.join(wwv_flow_t_varchar2(
    '<div class="u-display-flex u-flex-wrap u-align-items-center u-gap-3 u-text-muted u-text-sm">',
    '  {if BUSINESS_UNIT/}<span class="u-display-flex u-align-items-center u-gap-2"><span class="fa fa-building-o" aria-hidden="true"></span>&BUSINESS_UNIT.</span>{endif/}',
    '  {if COUNTRY/}<span class="u-display-flex u-align-items-center u-gap-2"><span class="fa fa-map-marker-o" aria-hidden="true"></span>&COUNTRY.</span>{endif/}',
    '  {if HIRE_DATE/}<span class="u-display-flex u-align-items-center u-gap-2"><span class="fa fa-calendar" aria-hidden="true"></span>&HIRE_DATE_DISPLAY.</span>{endif/}',
    '  {if CAREER_LEVEL/}<span class="u-display-flex u-align-items-center u-gap-2"><span class="fa fa-signal" aria-hidden="true"></span> &CAREER_LEVEL.</span>{endif/}',
    '</div>')),
  'DISPLAY_AVATAR', 'Y',
  'DISPLAY_BADGE', 'Y',
  'HIDE_BORDERS', 'N',
  'OVERLINE', '&WORK_ARRANGEMENT.',
  'REMOVE_PADDING', 'N',
  'STACK_MOBILE', 'N',
  'TITLE', '&NAME.')).to_clob
,p_plug_comment=>'Uses the title-link and compact row-menu pattern from ux-pattern-catalog page 220. Each employee row includes an image avatar, a department badge, and profile and email actions. Order By varies the presentation order.'
);
