,p_plug_name=>'Employees'
,p_static_id=>'employees_1'
,p_region_name=>'employees_1'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc:t-CardsRegion--styleC:t-Form--large'
,p_plug_template=>2076152157930740558
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select EMPLOYEE_ID,',
'       FIRST_NAME,',
'       LAST_NAME,',
'       EMAIL,',
'       JOB_TITLE,',
'       initcap(EMPLOYMENT_STATUS) as EMPLOYMENT_STATUS,',
'       case EMPLOYMENT_STATUS when ''ACTIVE'' then ''u-success'' ',
'            when ''INACTIVE'' then ''u-danger''',
'            when ''LEAVE'' then ''u-warning''',
'       end BADGE_STATE,',
'      case EMPLOYMENT_STATUS when ''ACTIVE'' then ''fa-check-circle-o'' ',
'            when ''INACTIVE'' then ''fa-times-circle-o''',
'            when ''LEAVE'' then ''fa-minus-circle-o''',
'       end BADGE_ICON,',
'       CAREER_LEVEL,',
'       COST_CENTER_DESCRIPTION,',
'       BUSINESS_UNIT,',
'       TIMEZONE,',
'       WORK_ARRANGEMENT,',
'       AVATAR',
'  from FSP_EMPLOYEES E, FSP_COST_CENTERS CC',
'  where E.COST_CENTER_ID = CC.COST_CENTER_ID'))
,p_query_order_by_type=>'ITEM'
,p_query_order_by=>'{"orderBys":[{"key":"REPORTS1","expr":"FIRST_NAME DESC"},{"key":"REPORTS2","expr":"LAST_NAME ASC"},{"key":"DEPTNO","expr":"JOB_TITLE ASC"}],"itemName":"P5_ORDER_BY"}'
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
