wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(11191910747021854457)
,p_plug_name=>'Workforce Locations'
,p_static_id=>'fs_04_map'
,p_icon_css_classes=>'fa-map-marker'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:js-showMaximizeButton'
,p_plug_template=>4075786578761660127
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select l.location_id,',
'       l.location_name,',
'       l.office_type,',
'       initcap(replace(l.office_type, ''_'', '' '')) as office_type_label,',
'       l.city,',
'       c.country_name,',
'       c.region as geographic_region,',
'       l.location_status,',
'       initcap(lower(l.location_status)) as location_status_label,',
'       l.opened_date,',
'       to_char(',
'         l.opened_date,',
'         ''FMMonth YYYY'',',
'         ''NLS_DATE_LANGUAGE=English''',
'       ) as opened_month,',
'       to_char(l.opened_date, ''YYYY-MM'') as opened_month_key,',
'       to_char(',
'         l.opened_date,',
'         ''DD Mon YYYY'',',
'         ''NLS_DATE_LANGUAGE=English''',
'       ) as opened_date_display,',
'       l.timezone,',
'       case l.office_type',
'         when ''HEADQUARTERS'' then ''fa-building''',
'         when ''REGIONAL'' then ''fa-building-o''',
'         when ''SATELLITE'' then ''fa-map-marker''',
'         else ''fa-wifi''',
'       end as marker_icon,',
'       case l.office_type',
'         when ''HEADQUARTERS'' then ''#056AC8''',
'         when ''REGIONAL'' then ''#117733''',
'         when ''SATELLITE'' then ''#C66A00''',
'         else ''#6B7280''',
'       end as marker_color,',
'       l.capacity,',
'       l.latitude,',
'       l.longitude,',
'       nvl(ec.employee_count, 0) as employee_count',
'  from fsp_locations l',
'  join fsp_countries c',
'    on c.country_code_alpha2 = l.country_code_alpha2',
'  left join (',
'    select location_id,',
'           count(*) as employee_count',
'      from fsp_employees',
'     group by location_id',
'  ) ec',
'    on ec.location_id = l.location_id',
' order by l.location_name;'))
,p_lazy_loading=>true
,p_plug_source_type=>'NATIVE_MAP_REGION'
,p_landmark_label=>'Workforce location map'
);
