wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(12815286449192092755)
,p_plug_name=>'Employees'
,p_static_id=>'search-results'
,p_region_name=>'search-results'
,p_region_template_options=>'#DEFAULT#:t-ContentBlock--h1:t-ContentBlock--lightBG:t-Region--removeHeader js-removeLandmark'
,p_plug_template=>2325543309974442989
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'    fe.employee_id,',
'    fe.first_name || '' '' || fe.last_name as name,',
'    fe.job_title,',
'    fcc.business_unit,',
'    fe.email,',
'    fe.phone_country_code || '' '' || fe.phone_number as phone_number,',
'    fe.tags as tags_json,',
'    (',
'        select listagg(jt.tag_value, '':'')',
'                   within group (order by jt.tag_order)',
'        from json_table(',
'            fe.tags,',
'            ''$[*]'' columns (',
'                tag_order for ordinality,',
'                tag_value varchar2(4000) path ''$''',
'            )',
'        ) jt',
'    ) as tags_list,',
'    initcap(fe.work_arrangement) as work_arrangement,',
'    to_char(fe.hire_date, ''DD Mon YYYY'') as hire_date,',
'    initcap(fe.employment_status) as employment_status,',
'    fe.country,',
'    fe.career_level,',
'    case fe.employment_status',
'        when ''ACTIVE''   then ''success''',
'        when ''INACTIVE'' then ''danger''',
'        when ''LEAVE''    then ''warning''',
'    end as badge_state,',
'    case fe.employment_status',
'        when ''ACTIVE''   then ''fa-check-circle-o''',
'        when ''INACTIVE'' then ''fa-times-circle-o''',
'        when ''LEAVE''    then ''fa-minus-circle-o''',
'    end as badge_icon,',
'    fe.avatar',
'from fsp_employees fe',
'join fsp_cost_centers fcc',
'    on fe.cost_center_id = fcc.cost_center_id'))
,p_query_order_by_type=>'ITEM'
,p_query_order_by=>'{"orderBys":[{"key":"BUSINESS_UNIT","expr":"BUSINESS_UNIT ASC"},{"key":"JOB_TITLE","expr":"JOB_TITLE ASC"},{"key":"ENAME","expr":"NAME ASC"}],"itemName":"P20_ORDER_BY"}'
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$CONTENT_ROW'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>false
,p_row_selection_type=>'MULTIPLE'
,p_select_all_page_item=>'P20_SELECT_ALL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'APPLY_THEME_COLORS', 'Y',
  'AVATAR_IMAGE', '{"source":"URL","url":"#APEX_FILES#sample_data&AVATAR."}',
  'AVATAR_SHAPE', 't-Avatar--circle',
  'AVATAR_TYPE', 'image',
  'DESCRIPTION', wwv_flow_string.join(wwv_flow_t_varchar2(
    '&EMAIL.',
    '',
    '{if TAGS_LIST/}<br>{loop ":" TAGS_LIST/}',
    '{with/}',
    '  LABEL:=Tag',
    '  VALUE:=&APEX$ITEM.',
    '  LABEL_DISPLAY:=N',
    '  STYLE:=t-Badge--subtle t-Badge--circle u-text-muted-color',
    '  SIZE:=t-Badge--md',
    '{apply THEME$BADGE/}{endloop/}{endif/}')),
  'DISPLAY_AVATAR', 'Y',
  'DISPLAY_BADGE', 'N',
  'GROUP_TITLE', '&BUSINESS_UNIT.',
  'HIDE_BORDERS', 'N',
  'MISC', 'Business Unit: &BUSINESS_UNIT.',
  'OVERLINE', '&WORK_ARRANGEMENT.',
  'REMOVE_PADDING', 'N',
  'STACK_MOBILE', 'N',
  'TITLE', '&NAME.')).to_clob
,p_plug_comment=>'Uses the title-link and compact row-menu pattern from ux-pattern-catalog page 220. Each employee row includes an image avatar, a department badge, and profile and email actions. Order By varies the presentation order.'
);
